mapper.update:
update dishes set featured_at = current_timestamp(6)
where merchant_id = #{merchantId} and id = #{dishId}
  and status = 'active' and featured_at is null

update dish_categories
set name = #{name}, sort_order = #{sortOrder}, enabled = #{enabled}
where merchant_id = #{merchantId} and id = #{id}

mapper.select:
select id, merchant_id, name, category, unit, 0 as referenced_dish_count, null as referenced_dish_names
from merchant_ingredients
where merchant_id = #{merchantId} and id = #{ingredientId}

mapper.update:
update merchant_ingredients
set name = #{name}, category = #{category}, unit = #{unit}
where merchant_id = #{merchantId} and id = #{id}
